// Change the scale to `n` without changing the value; a value that would change raises.
//
// `rescale(n)` changes the scale **without changing the value**: it pads, and it narrows only when the digits it
// drops are zeros. A value that would change raises — `round(n, mode)` is the spelling that changes it, and it
// names how. That makes `rescale(n)` the check that a value is already on a grid:
//
// ```go
// (1.5d).rescale(3).format("s")     // => "1.500"
// (1.500d).rescale(1).format("s")   // => "1.5" — only zeros dropped
// (1.55d).rescale(1)                // Error: invalid_value: (rescale) 1.55 has non-zero digits past scale 1; use round(n, mode) to round it
// (1.5d).rescale(40)                // Error: invalid_value: (rescale) scale must be between 0 and 19
// ```
//
//kavun:member rescale pure (n) -> decimal
func decimalRescale(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	name := id.String()
	o := (*dec128.Dec128)(v.Ptr)
	scale, err := decimalScaleArg(name, "scale", args[0])
	if err != nil {
		return Undefined, err
	}
	r, inexact := o.RescaleRoundInexact(scale, dec128.ROUND_TOWARD_ZERO)
	if inexact {
		return Undefined, errs.NewInvalidValueError(fmt.Sprintf(
			"(%s) %s has non-zero digits past scale %d; use round(n, mode) to round it", name, o.StringFixed(), scale))
	}
	return decimalResult(name, r)
}

