// decimalRoundFixed is round_<mode>(places): round(places, mode) with the mode fixed by the member.
func decimalRoundFixed(v Value, id member.ID, args []Value, mode string) (Value, error) {
	name := id.String()
	o := (*dec128.Dec128)(v.Ptr)
	places, err := decimalPlacesArg(name, "places", args[0])
	if err != nil {
		return Undefined, err
	}
	return decimalResult(name, decimalRoundTo(*o, places, roundingModes[mode].dec128()))
}

// Round to a multiple of `m` with the rounding `mode`.
//
// ```go
// (2.37d).round_to_multiple(0.05d, "half_up")    // => 2.35d — Swiss/Swedish cash rounding; the result has m's scale
// (183.47d).round_to_multiple(10, "ceiling")     // => 190d — "the next whole 10"
// (2.37d).round_to_multiple(0, "half_up")        // Error: invalid_value: (round_to_multiple) the multiple must be positive, got 0
// ```
//
//kavun:member round_to_multiple pure (m, mode) -> decimal
func decimalRoundToMultiple(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	name := id.String()
	o := (*dec128.Dec128)(v.Ptr)
	m, err := decimalOperandArg(name, "first", args[0])
	if err != nil {
		return Undefined, err
	}
	if !m.IsPositive() {
		return Undefined, errs.NewInvalidValueError(fmt.Sprintf("(%s) the multiple must be positive, got %s", name, m.StringFixed()))
	}
	mode, err := decimalModeArg(name, "mode", args[1])
	if err != nil {
		return Undefined, err
	}
	return decimalResult(name, o.RoundToMultiple(m, mode))
}

// Round to at most `k` significant digits with the rounding `mode`.
//
// ```go
// (1.09875d).round_significant(5, "half_even")   // => 1.0988d — at most 5 significant digits, an FX quote
// (9.99d).round_significant(2, "half_up")        // => 10.0d — the carry adds a digit no scale can drop
// ```
//
//kavun:member round_significant pure (k, mode) -> decimal
func decimalRoundSignificant(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	name := id.String()
	o := (*dec128.Dec128)(v.Ptr)
	digits, err := decimalCountArg(name, "digits", args[0])
	if err != nil {
		return Undefined, err
	}
	mode, err := decimalModeArg(name, "mode", args[1])
	if err != nil {
		return Undefined, err
	}
	return decimalResult(name, o.RoundToSignificant(uint8(min(digits, 255)), mode))
}

// Divide by `y`, rounding once to scale `n` with `mode`; see [the `*_round`
