// Answer `[quotient, remainder]` of division by `y`, the quotient truncated toward zero.
//
// ```go
// (-7.5d).quo_rem(2)               // => [-3d, -1.5d] — quotient truncated toward zero, as Python's divmod on Decimal
// q, r := (17d).quo_rem(5)         // q = 3d, r = 2d; q * y + r == x exactly
// (1d).quo_rem(0)                  // Error: division_by_zero
// ```
//
//kavun:member quo_rem pure (y) -> [quotient, remainder]
func decimalQuoRem(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	name := id.String()
	o := (*dec128.Dec128)(v.Ptr)
	other, err := decimalOperandArg(name, "first", args[0])
	if err != nil {
		return Undefined, err
	}
	q, r := o.QuoRem(other)
	qv, err := decimalResult(name, q)
	if err != nil {
		return Undefined, err
	}
	rv, err := decimalResult(name, r)
	if err != nil {
		return Undefined, err
	}
	return NewArrayValue([]Value{qv, rv}, false), nil
}

// Multiply by 10ⁿ as a move of the point, never rounded.
